layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 3px solid var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid var(--ryt-text); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: 1px; text-underline-offset: 2.88px; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 56px; font-weight: 900; font-style: normal; line-height: 1.05; letter-spacing: -4.512px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 900; font-style: normal; line-height: 1.05; letter-spacing: -4.512px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace; font-size: 16px; font-weight: 900; font-style: normal; line-height: 1.5; letter-spacing: -0.32px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-bottom: 1px solid var(--ryt-text); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace; font-size: 14px; font-weight: 900; font-style: normal; line-height: 1.25; letter-spacing: 0.56px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 12px; padding-bottom: 0px; padding-left: 12px; transition: all }
[data-ryt="button"] { color: var(--ryt-text); background-color: rgb(212, 255, 63); border-top: 1px solid var(--ryt-text); border-right: 1px solid var(--ryt-text); border-bottom: 1px solid var(--ryt-text); border-left: 1px solid var(--ryt-text); border-radius: 0px; box-shadow: var(--ryt-text) 3px 3px 0px 0px; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace; font-weight: 900; font-style: normal; line-height: 1.25; letter-spacing: 0.56px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 16px; padding-bottom: 0px; padding-left: 16px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace; font-size: 13px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 900; font-style: normal; letter-spacing: -0.6px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 900; font-style: normal; line-height: 1.2; letter-spacing: -0.6px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: initial; text-decoration-thickness: 2px; text-underline-offset: 0.16em }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: initial; text-decoration-thickness: 2px; text-underline-offset: 0.16em }
[data-ryt="button"]:hover { box-shadow: 2px 2px 0 0 #171715 }
[data-ryt="nav"] a:hover { text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: initial; text-decoration-thickness: 2px; text-underline-offset: 0.16em }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-thickness: 2px }
